function xorAfterQueries(nums: number[], queries: number[][]): number {
    const mod = 1e9 + 7;
    for (const [l, r, k, v] of queries) {
        for (let idx = l; idx <= r; idx += k) {
            nums[idx] = (nums[idx] * v) % mod;
        }
    }
    return nums.reduce((acc, x) => acc ^ x, 0);
}

class Solution:
    def xorAfterQueries(self, nums: List[int], queries: List[List[int]]) -> int:
        MOD = 1_000_000_007
        n = len(nums)
        B = int(math.isqrt(n)) + 1

        # events[k][res] = list of (t, v)
        events = [[[] for _ in range(k)] for k in range(B + 1)]

        for l, r, k, v in queries:
            if k > B:
                for idx in range(l, r + 1, k):
                    nums[idx] = nums[idx] * v % MOD
            else:
                res = l % k
                t1 = (l - res) // k
                t2 = (r - res) // k
                events[k][res].append((t1, v))

                if t2 + 1 <= (n - 1 - res) // k:
                    invv = pow(v, MOD - 2, MOD)
                    events[k][res].append((t2 + 1, invv))

        for k in range(1, B + 1):
            for res in range(k):
                ev = events[k][res]
                if not ev:
                    continue

                ev.sort()
                comp = []
                for t, val in ev:
                    if comp and comp[-1][0] == t:
                        comp[-1] = (t, comp[-1][1] * val % MOD)
                    else:
                        comp.append([t, val])

                cur = 1
                ptr = 0
                t = 0
                idx = res
                while idx < n:
                    while ptr < len(comp) and comp[ptr][0] == t:
                        cur = cur * comp[ptr][1] % MOD
                        ptr += 1
                    nums[idx] = nums[idx] * cur % MOD
                    idx += k
                    t += 1

        xr = 0
        for x in nums:
            xr ^= x
        return xr

class Solution {
    static constexpr int MOD = 1000000007;

    long long modpow(long long a, long long e) {
        long long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if (e & 1) { r = (r * a) % MOD; }
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

public:
    int xorAfterQueries(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        int B = sqrt(n) + 1;

        vector<vector<vector<pair<int, int>>>> events(B + 1);
        for (int k = 1; k <= B; ++k) {
            events[k].resize(k);
        }

        for (auto& qq : queries) {
            int l = qq[0], r = qq[1], k = qq[2], v = qq[3];
            if (k > B) {
                for (int idx = l; idx <= r; idx += k) {
                    nums[idx] = (long long) nums[idx] * v % MOD;
                }
            } else {
                int res = l % k;
                int t1 = (l - res) / k;
                int t2 = (r - res) / k;
                events[k][res].push_back({t1, v});

                if (t2 + 1 <= (n - 1 - res) / k) {
                    int invv = modpow(v, MOD - 2);
                    events[k][res].push_back({t2 + 1, invv});
                }
            }
        }

        for (int k = 1; k <= B; ++k) {
            for (int res = 0; res < k; ++res) {
                auto& ev = events[k][res];
                if (ev.empty()) {
                    continue;
                }

                sort(ev.begin(), ev.end());
                vector<pair<int, int>> comp;

                for (auto& p : ev) {
                    if (!comp.empty() && comp.back().first == p.first) {
                        comp.back().second = (long long) comp.back().second * p.second % MOD;
                    } else {
                        comp.push_back(p);
                    }
                }

                long long cur = 1;
                int ptr = 0;
                int t = 0;
                for (int idx = res; idx < n; idx += k, ++t) {
                    while (ptr < comp.size() && comp[ptr].first == t) {
                        cur = (cur * comp[ptr].second) % MOD;
                        ++ptr;
                    }
                    nums[idx] = nums[idx] * cur % MOD;
                }
            }
        }

        int xr = 0;
        for (int x : nums) {
            xr ^= x;
        }

        return xr;
    }
};

